import java.util.*;

class Solution {
    public int happyKids(int[] need, int[] sizes) {
        int[] k = need.clone(), s = sizes.clone();
        Arrays.sort(k);
        Arrays.sort(s);
        int i = 0, j = 0;
        while (i < k.length && j < s.length) {
            if (s[j] >= k[i]) i++;   // smallest snack that fits this kid
            j++;                     // snack used or too small for anyone left
        }
        return i;
    }
}

