function happyKids(need, sizes) {
  const n = need.slice().sort((a, b) => a - b), s = sizes.slice().sort((a, b) => a - b);
  let i = 0;
  for (const x of s) if (i < n.length && x >= n[i]) i++;
  return i;
}
